:root {
  color-scheme: light;
  font-family: system-ui, sans-serif;
  color: #281d21;
  background: #faf3ec;
  line-height: 1.5;
}
* { box-sizing: border-box; }
body { margin: 0; }
main { max-width: 56rem; margin: auto; padding: clamp(0.75rem, 3vw, 1.75rem); }
h1, h2, h3 { margin: 0 0 0.5rem; line-height: 1.2; }
h1 { font: 700 clamp(1.6rem, 4vw, 2.3rem)/1.15 Georgia, serif; }
h2 { font-size: 1.1rem; }
h3 { font-size: 1rem; }
p { margin: 0.45rem 0; }
.lookup { margin: 1rem 0; }
label { display: block; font-size: 0.9rem; }
.entry, .forms { display: flex; flex-wrap: wrap; gap: 0.45rem; margin: 0.35rem 0; }
input, button { font: inherit; border-radius: 0.35rem; padding: 0.4rem 0.7rem; }
input { flex: 1 1 12rem; min-width: 0; border: 1px solid #91687a; color: inherit; }
button { border: 1px solid #763652; background: #763652; color: white; cursor: pointer; }
button:hover { background: #5f2940; }
button:focus-visible, input:focus-visible { outline: 3px solid #9b4e18; outline-offset: 2px; }
#reset, .forms button { background: #fff9fa; color: #652b43; }
#reset:hover, .forms button:hover { background: #f7e2ec; }
.result { border-inline-start: 4px solid #8c385b; background: #fffafa; padding: 0.65rem 0.85rem; margin-top: 0.7rem; }
#pair { font: 700 clamp(1.3rem, 4vw, 1.75rem)/1.3 Georgia, serif; overflow-wrap: anywhere; }
#accent { font-weight: 700; }
mark { color: #512138; background: #f4cadc; padding: 0.02em 0.12em; border-radius: 0.15em; }
.rules { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0.65rem; }
.rule { border: 1px solid #ddbdca; padding: 0.65rem 0.85rem; border-radius: 0.45rem; background: #fffafa; }
.forms button { max-width: 100%; overflow-wrap: anywhere; }
@media (max-width: 34rem) { .rules { grid-template-columns: 1fr; } }

