(() => {
  const antepenult = 'Acute on the antepenult (third syllable from the end)';
  const penult = 'Circumflex on the penult (second syllable from the end)';
  const rules = [
    {
      name: 'Feminine derivatives of the same meaning',
      accent: antepenult,
      examples: [
        {base: 'Πηνελόπη', syllables: ['Πη', 'νε', 'λό', 'πει', 'α']},
        {base: 'χαλκοβαρής', syllables: ['χαλ', 'κο', 'βά', 'ρει', 'α']},
        {base: 'ἠριγενής', syllables: ['ἠ', 'ρι', 'γέ', 'νει', 'α'], note: 'Herodian glosses the base as “born in the air”.'}
      ]
    },
    {
      name: 'Titles of written works',
      accent: antepenult,
      examples: [
        {syllables: ['Ὀ', 'δύσ', 'σει', 'α']},
        {syllables: ['Τη', 'λε', 'γό', 'νει', 'α']}
      ]
    },
    {
      name: 'Derivatives of barytone -υς words',
      accent: antepenult,
      note: 'The base is accented somewhere before the final syllable.',
      examples: [
        {base: 'ἥμισυς', syllables: ['ἡ', 'μί', 'σει', 'α']},
        {base: 'θῆλυς', syllables: ['θή', 'λει', 'α']}
      ]
    },
    {
      name: 'Derivatives of oxytone -υς words',
      accent: penult,
      note: 'The base has an acute accent on the final syllable.',
      examples: [
        {base: 'ταχύς', syllables: ['τα', 'χεῖ', 'α']},
        {base: 'βραδύς', syllables: ['βρα', 'δεῖ', 'α']},
        {base: 'πλατύς', syllables: ['πλα', 'τεῖ', 'α']},
        {base: 'τραχύς', syllables: ['τρα', 'χεῖ', 'α'], note: 'Herodian quotes Strabo, book 14, on the part of Cilicia called τραχεῖα.'},
        {base: 'ὀξύς', syllables: ['ὀ', 'ξεῖ', 'α']}
      ]
    },
    {
      name: 'Exceptions listed after the oxytone rule',
      accent: antepenult,
      examples: [
        {base: 'λιγύς', syllables: ['λί', 'γει', 'α']},
        {base: 'ἐλαχύς', syllables: ['ἐ', 'λά', 'χει', 'α']},
        {syllables: ['θά', 'λει', 'α'], note: 'Herodian lists this alongside λίγεια and ἐλάχεια.'}
      ]
    }
  ];

  const word = document.querySelector('#word');
  const result = document.querySelector('#result');
  const key = text => text.trim().normalize('NFD').toLowerCase()
    .replace(/\p{M}/gu, '').replace(/ς/g, 'σ');
  const examples = new Map();

  function element(tag, text, id) {
    const node = document.createElement(tag);
    if (text) node.textContent = text;
    if (id) node.id = id;
    return node;
  }

  function show(example, rule) {
    const pair = element('p', '', 'pair');
    pair.lang = 'el';
    if (example.base) pair.append(example.base, ' → ');
    const accentIndex = example.syllables.length - (rule.accent === penult ? 2 : 3);
    example.syllables.forEach((syllable, index) => {
      pair.append(index === accentIndex ? element('mark', syllable) : syllable);
    });
    result.replaceChildren(pair, element('p', rule.accent, 'accent'), element('p', rule.name, 'rule'));
    if (rule.note) result.append(element('p', rule.note));
    if (example.note) result.append(element('p', example.note));
  }

  function lookup() {
    const query = key(word.value);
    const match = examples.get(query);
    if (match) {
      show(match.example, match.rule);
      return;
    }
    result.textContent = query
      ? 'No listed example matches. Choose a form below.'
      : 'Enter a Greek form or choose an example below.';
  }

  const groups = document.querySelector('#rules');
  for (const rule of rules) {
    const group = element('section');
    group.className = 'rule';
    const buttons = element('div');
    buttons.className = 'forms';
    for (const example of rule.examples) {
      const form = example.syllables.join('');
      examples.set(key(form), {example, rule});
      if (example.base) examples.set(key(example.base), {example, rule});
      const button = element('button', form);
      button.type = 'button';
      button.lang = 'el';
      button.addEventListener('click', () => {
        word.value = form;
        show(example, rule);
      });
      buttons.append(button);
    }
    group.append(element('h3', rule.name), element('p', rule.accent), buttons);
    groups.append(group);
  }

  document.querySelector('#lookup').addEventListener('submit', event => {
    event.preventDefault();
    lookup();
  });
  document.querySelector('#reset').addEventListener('click', () => {
    word.value = '';
    lookup();
    word.focus();
  });
  lookup();
})();

